-- V68：保留“成长好习惯”原有十篇故事，追加四篇长篇故事及理解问答。
-- 每篇十二页，描写选择、连锁影响、无法撤回的损失与持续补救；不以羞辱或体罚推动成长。

INSERT INTO unit (id, theme_id, name, sort_order, is_locked) VALUES
(153, 49, '没有开上展台的列车', 11, 0),
(154, 49, '再也拼不回的那一页', 12, 0),
(155, 49, '幕布后空着的位置', 13, 0),
(156, 49, '被藏起来的裂缝', 14, 0);

INSERT INTO lesson (id, unit_id, name, type, content, sort_order, star_reward) VALUES
(619, 153, '没有开上展台的列车', 'READING', '{
  "type":"READING",
  "items":[
    {"title":"一张属于三个人的邀请卡","content":"社区小小创客展的邀请卡寄到学校时，安安把它读了三遍。她和乐乐做车站，彭泽宇做跨河纸桥，三个人要让小列车穿过整座模型城。这是他们第一次得到正式展演的名额，爷爷奶奶也答应来看。周老师把周五下午的试车时间圈出来：只有整条线路试过，周六才能搬上展台。彭泽宇摸着邀请卡上的小火车，觉得自己已经听到了掌声。","image":"growth-consequences/missed-exhibition"},
    {"title":"还早呢，先铺一条支线","content":"星期一，彭泽宇画好桥头，却没有量河面的宽度。爸爸问要不要现在找纸板，他说还早，先给家里的玩具铁路加条支线。星期二，他又给小车贴窗户。安安发来车站照片，问桥什么时候能接上。他回了一句快好了，随后把任务本合上。纸上那道漂亮的桥还没有变成能拿起来的东西，可他看着画，竟觉得自己已经做了一大半。","image":"growth-consequences/missed-exhibition"},
    {"title":"第一次提醒没有留下来","content":"星期三，乐乐带来接口尺寸，提醒他桥两端必须和轨道一样高。彭泽宇把尺寸条塞进口袋，说晚上一定动手。回家后，他想先挑桥的颜色，又花了很久画旗子。妈妈指着任务本问：桥身、桥墩、连接和试车，今天准备做哪一步？他有点不耐烦，觉得大家都把简单的事说复杂了。睡前翻出纸板时，他才发现口袋里的尺寸条已经揉成一团。","image":"growth-consequences/missed-exhibition"},
    {"title":"最后一晚忽然变短","content":"星期四晚上，他终于量好长度，却发现一整块纸板不够，只能把两块接起来。桥墩立起又倒下，连接处总是翘边。爸爸陪他重新折支撑，提醒胶要按说明等干，着急也不能省掉。彭泽宇盯着时钟，第一次希望钟针能往回走。他删掉了旗子，删掉了栏杆，最后连试车也删掉了：明天到学校再说吧。桌上留下的，是一座看起来像桥的桥。","image":"growth-consequences/missed-exhibition"},
    {"title":"列车停在河中央","content":"周五试车，安安把车站灯打开，乐乐蹲下来对准轨道。小列车刚到纸桥中央，连接处便往下折，车头卡住，后面的车厢挤歪了。老师立即关掉玩具电源。没有人受伤，可一侧桥墩已经压扁，轨道接口也被扯开。彭泽宇赶紧拿起胶带：我马上就能修好！老师让他先看看歪掉的桥面。这次需要重新做支撑，贴住表面还不能让整座桥可靠。","image":"growth-consequences/missed-exhibition"},
    {"title":"名额不会停下来等","content":"三个人一起帮忙量尺寸、拆旧桥墩，仍没能在试车结束前修好。周老师联系展馆，问能不能延后交模型。对方解释，展台和用电安排当天就要检查完成，第二天不能临时搬进未经检查的作品。彭泽宇举着胶带的手慢慢垂下。错过的不是几分钟自由活动，而是他们准备了好几个星期的正式展演。邀请卡上的时间没有变，属于他们的那个名额却只能空出来。","image":"growth-consequences/missed-exhibition"},
    {"title":"车站的灯还亮着","content":"安安没有马上说话。她关掉车站灯，把贴了许多小窗户的纸屋装回盒子。乐乐问：你说快好了的时候，究竟做好了多少？彭泽宇很想说纸板太软，又知道那不是全部原因。他低头回答：只有图。我一直没有开始做桥。乐乐把准备送给爷爷的座位卡收进口袋。那张卡折起来的声音很轻，彭泽宇却觉得比谁大声责备他都难受。","image":"growth-consequences/missed-exhibition"},
    {"title":"一句对不起搬不回展台","content":"他向两位伙伴道歉，请老师陪着自己给受邀的家人说明原因。爷爷说知道了，没有责骂，也没有说这不算什么。安安告诉他：我愿意以后再试，可我今天还是很难过。彭泽宇点点头，没有催她原谅自己。周六，他们以观众身份走进展馆，看见别人的列车经过桥梁。自己的模型留在学校。爸爸陪他坐了一会儿，等他自己站起来，再一起把剩下的展品看完。","image":"growth-consequences/missed-exhibition"},
    {"title":"从漂亮的封面翻到第一步","content":"星期日，彭泽宇重新打开任务本。这一次他没画封面，先写量尺寸，再写做桥墩、装桥面、等胶干和整线试车，每一步留出一天。他把新计划拿给伙伴看，问他们愿不愿意让他修好桥。乐乐提出，周三必须看到能站稳的桥墩，不能只听快好了。彭泽宇答应了，也请爸爸每天陪他核对一次实际做完的部分。任务本第一次有了能让别人检查的进度。","image":"growth-consequences/missed-exhibition"},
    {"title":"第二次也没有一遍成功","content":"新桥第一次试车仍有点晃。彭泽宇的脸热了，他差点又说没问题。可是这次距离约好的展示还有三天，他停下列车，把摇晃的位置圈出来，请老师帮忙判断。他和伙伴加宽桥墩，等连接处稳固后，先试一节车厢，再试整列车。傍晚，火车来回通过了几次。安安终于重新打开车站灯，灯光照在新桥上，也照着他们没有被匆忙挤掉的检查记录。","image":"growth-consequences/missed-exhibition"},
    {"title":"迟来的掌声有另一种声音","content":"老师安排他们在班级分享会上演示模型，三个人轮流讲制作过程。彭泽宇没有跳过失败的那一段。他拿起压扁的旧桥墩，说自己把准备时间花掉了，让伙伴也失去了机会。教室里响起掌声，爷爷通过家人录的视频看到了列车。但班级分享不是那次社区展演，原来的名额没有回来。彭泽宇把两张活动记录都夹进本子里，不再只留下好看的那一张。","image":"growth-consequences/missed-exhibition"},
    {"title":"这一次，先把桥墩拿出来","content":"一个月后，班级要做新的模型。彭泽宇仍然很想先画彩旗，手已经伸向彩笔，看到任务本里那张旧邀请卡，又停住了。他把尺子、纸板和今天的尺寸放到桌上，先做第一个桥墩。晚上给伙伴看进度时，他说的是两个桥墩完成，桥面还没做。窗外天色渐暗，小火车安静停在一旁。他知道它会等自己玩，也知道有些约定不会一直等。","image":"growth-consequences/missed-exhibition"}
  ]
}', 1, 3),
(620, 153, '展台与约定问答', 'QUIZ', '{
  "type":"QUIZ",
  "items":[
    {"question":"让全组失去正式展演机会的原因链是什么？","options":["旗子画得少，车站不够漂亮","一再拖延，制作和试车不足，错过检查期限","伙伴没有准备车站"],"answer":1,"image":"growth-consequences/missed-exhibition"},
    {"question":"周五贴住桥面的裂口，为什么仍不能立即参展？","options":["支撑需要重做，还要经过完整试车检查","只要颜色不同就不能参展","老师不喜欢纸桥"],"answer":0,"image":"growth-consequences/missed-exhibition"},
    {"question":"安安说愿意再试，但今天仍然难过，说明什么？","options":["她已经不愿意做任何模型","道歉没有任何用处","她可以接受补救，同时需要时间消化失望"],"answer":2,"image":"growth-consequences/missed-exhibition"},
    {"question":"哪种进度说明能帮助伙伴安排接下来的工作？","options":["放心吧，肯定没问题","两个桥墩完成，桥面还没做","我在心里想得很认真"],"answer":1,"image":"growth-consequences/missed-exhibition"},
    {"question":"班级分享成功后，哪件事仍然无法挽回？","options":["他们已经错过那一次社区正式展演","小列车永远不能再行驶","伙伴永远不会再合作"],"answer":0,"image":"growth-consequences/missed-exhibition"},
    {"question":"如果周三发现材料不够，怎样做更可靠？","options":["继续装饰封面，等最后一天再说","先告诉伙伴已经全部做好","及时说明缺少什么，请大人协助调整并保留试车时间"],"answer":2,"image":"growth-consequences/missed-exhibition"}
  ]
}', 2, 3),

(621, 154, '再也拼不回的那一页', 'READING', '{
  "type":"READING",
  "items":[
    {"title":"奶奶带来的蓝布册子","content":"奶奶从柜子里取出一本蓝布封面的纪念册，说学校的家庭故事会可以讲讲里面的小院子。那是她小时候住过的地方，如今已经拆掉了。册子里夹着旧车票、照片，还有爷爷年轻时画的院子水彩画。画里一棵石榴树伸过屋檐，门前有两个很小的人。彭泽宇问能不能带回家仔细看。奶奶想了想，把册子放进保护袋：可以，请替我照顾好这些只有一份的东西。","image":"growth-consequences/damaged-memory-book"},
    {"title":"临时放一下的地方","content":"回家后，妈妈和他一起清出书架上的一格，专门放纪念册。彭泽宇翻完画，想照着搭一座积木小院，就把册子留在客厅矮桌上。积木、轨道和画笔越铺越多，保护袋被挤到椅子下面。妈妈提醒他先把册子送回书架，他回答等院子搭好就收。晚上要洗漱时，他又把桌面往旁边推了推。那一格干净的书架空着，借来的东西却在杂物里过夜。","image":"growth-consequences/damaged-memory-book"},
    {"title":"水瓶旁边还有一点空","content":"第二天下午，他喝水回来，看见桌面只剩纪念册旁边有个空隙，就把没有拧紧的水瓶搁在那里。玩具火车钻进桌子下，他弯腰去捡，袖口扫到了瓶身。水瓶倒下时声音并不大，水却很快穿过画笔和纸片，流进摊开的册子。他赶紧扶起瓶子，发现那幅石榴树的画正在变深。刚才还能看清的两个人影，被一圈缓缓扩散的颜色连到了一起。","image":"growth-consequences/damaged-memory-book"},
    {"title":"越着急，纸越薄","content":"彭泽宇抽来纸巾想用力擦，妈妈看见后立即让他停下，接过册子，小心把表面积水吸走。他站在桌旁问：晾干就好了，对不对？妈妈没有马上回答，只说先尽量减少损坏。那张旧纸被水浸过，边缘已经起皱，画上的颜色不再待在原来的地方。彭泽宇第一次发现，有些事情不是擦干桌子就能结束。他望着书架上那个空格，很想把昨天的自己叫回来。","image":"growth-consequences/damaged-memory-book"},
    {"title":"电话接通以前","content":"妈妈说应该告诉奶奶。彭泽宇握着电话，提议先买一本一模一样的册子，或者等干了再说。他怕奶奶不再借东西给自己，更怕听见奶奶难过。妈妈陪他把事情顺着说清：没归位，没收拾，水瓶没拧紧，最后碰倒了。电话接通，他一句一句讲完，没有说成水自己流过去了。听筒那边安静了一会儿，奶奶才问：石榴树下面那两个人，还能看清吗？","image":"growth-consequences/damaged-memory-book"},
    {"title":"原来画里是他们","content":"周末奶奶来看册子，告诉他画里的两个人是年轻的爷爷和她，旁边的小门通向他们住过的第一间屋子。那时没有拍下整座院子的照片，这幅画是唯一完整的样子。彭泽宇这才明白，损坏的不是一张可以再打印的纸。奶奶沿着干燥后弯曲的纸边看了很久，说自己需要把它带回家保管。他点头，把保护袋找出来，第一次没有再说借我多玩两天。","image":"growth-consequences/damaged-memory-book"},
    {"title":"有些颜色回不去了","content":"妈妈请教了做纸本文物修护的专业人员，对方查看后说明可以评估怎样保存这张画，但已经晕开的颜料不能保证回到原来的线条里。奶奶决定先好好保存，不让大家继续尝试擦洗。彭泽宇问重新画一张是不是就算修好了。奶奶说新画也可以珍贵，可它不会变回爷爷当年画下的这一张。他低下头，终于听懂了只有一份。一个新封面，换不回旧纸上的那个下午。","image":"growth-consequences/damaged-memory-book"},
    {"title":"先问需要什么帮助","content":"他把准备买玩具的零花钱拿出来，想买材料赔给奶奶。奶奶没有直接收下，而是请他先问家人打算怎样保存，别急着再买不合适的东西。最后，妈妈负责联系保存和装裱事宜，彭泽宇帮忙整理没有受潮的车票，并按奶奶的要求做标签。他还问能不能把小院子的故事录下来。奶奶同意了，但把原册放在自己身边，只让他一次拿一张已经确认能移动的卡片。","image":"growth-consequences/damaged-memory-book"},
    {"title":"一段没有颜色的录音","content":"录音开始时，奶奶说起雨打瓦片的声音，说起石榴熟了以后，爷爷总把最好的一颗留给她。彭泽宇一边听，一边画下她记得的位置。有的地方奶奶也想不清楚，两个人就留白，没有假装所有细节都找回来了。新的故事册慢慢有了内容，旧画上的人影却仍然模糊。每次停下录音，他都先把卡片按顺序还回托盘，再去拿水。奶奶看着，没有替他把这一步做掉。","image":"growth-consequences/damaged-memory-book"},
    {"title":"桌子重新有了边界","content":"回家后，他没有宣布从此再也不乱放，而是和妈妈一起调整桌面。喝水用旁边的小桌，借来的纸本看完就回保护袋，搭积木要先腾出自己的垫子。睡前两个人一起检查，前几天妈妈还需要提醒。有一次他想把漫画留在积木上，走到门口又回来，先找到书的位置。他发现收拾不是让房间像没住过人，而是别让下一件事把上一件重要的东西挤到危险的位置。","image":"growth-consequences/damaged-memory-book"},
    {"title":"故事会上那块空白","content":"家庭故事会那天，他带的是经过家人同意制作的新册，没有再借旧画。他给大家看石榴树的草图，也讲了自己把原画弄湿的经过。有人问为什么不把模糊的人影画得漂亮一点。他说那一块已经看不清了，不能假装这是原来的样子。老师让大家听了奶奶讲院子的录音。彭泽宇很高兴故事还能留下，又有点难过：大家听见了院子的声音，却看不到那幅完整的旧画了。","image":"growth-consequences/damaged-memory-book"},
    {"title":"归还时再多看一眼","content":"几个星期后，奶奶借给他一本普通画册，让他周日归还。彭泽宇先找好放书的位置，再把日期记下来。归还时，奶奶和他一起检查封面和书页，确认完整，才收进柜子。蓝布纪念册仍留在奶奶家，受损的那一页也没有奇迹般恢复。离开前，他把喝过水的杯子送回厨房。路过柜子时，他轻轻摸了摸自己口袋里的清单，知道照顾好借来的东西，要发生在弄坏之前。","image":"growth-consequences/damaged-memory-book"}
  ]
}', 1, 3),
(622, 154, '纪念册与整理问答', 'QUIZ', '{
  "type":"QUIZ",
  "items":[
    {"question":"这次损坏为什么不能简单地买一本新册子赔偿？","options":["奶奶只喜欢蓝色封面","所有纸张都不能购买","旧画记录独有的家庭记忆，新册子不能替代"],"answer":2,"image":"growth-consequences/damaged-memory-book"},
    {"question":"哪组行为一起增加了纪念册受损的风险？","options":["没有归位、桌面杂乱、没拧紧的水瓶放在旁边","先收好册子，再到另一张桌喝水","看完归还并检查书页"],"answer":0,"image":"growth-consequences/damaged-memory-book"},
    {"question":"弄湿旧画后，故事中的合适做法是什么？","options":["自己反复用力擦洗","及时告诉大人，让大人处理并寻求专业意见","藏起来，等没有人发现"],"answer":1,"image":"growth-consequences/damaged-memory-book"},
    {"question":"录音和新故事册带来了什么结果？","options":["让原画的颜色完全恢复","让奶奶必须立刻忘掉难过","保留更多家庭故事，但不能恢复受损原画"],"answer":2,"image":"growth-consequences/damaged-memory-book"},
    {"question":"奶奶把原册留在自己家，还愿意一起录故事，说明什么？","options":["她仍愿意陪伴，也可以设定保护物品的边界","她不允许彭泽宇学习任何故事","她已经觉得原画不重要了"],"answer":0,"image":"growth-consequences/damaged-memory-book"},
    {"question":"下一次借书前，哪项安排能真正减少同类问题？","options":["只保证自己一定会小心","先确定固定存放处，让饮水区与纸本分开","把书藏到连自己也找不到的地方"],"answer":1,"image":"growth-consequences/damaged-memory-book"}
  ]
}', 2, 3),

(623, 155, '幕布后空着的位置', 'READING', '{
  "type":"READING",
  "items":[
    {"title":"狐狸终于有了自己的声音","content":"社区影子剧场要演一出小动物找家的戏，彭泽宇得到小狐狸的角色。他练了很久，终于能让纸狐狸先探头、再摇尾巴，说出那句欢迎朋友的话。奶奶第一次来看他的正式演出，连座位都选好了。林老师告诉大家，演出安排在星期六上午，周五只做一次短彩排，晚上好好休息。彭泽宇把纸狐狸举到窗前，阳光在墙上投出长长的耳朵，他舍不得放下。","image":"growth-consequences/empty-stage-place"},
    {"title":"被悄悄加长的夜晚","content":"星期三晚上，他想再看一集动画找声音。爸爸提醒到了约好的收尾时间，他说只看结尾，却接着点开下一集。星期四，他又躺在被子里借着小灯给狐狸画衣服。妈妈发现后陪他收起纸笔，说没有做完可以明天继续。他点头，心里仍觉得少睡一点没关系。早晨起床越来越费劲，早餐时也常发呆。他把这些都当作小事，只想着台下的人会不会喜欢自己的狐狸。","image":"growth-consequences/empty-stage-place"},
    {"title":"彩排里漏掉的那一句","content":"周五彩排，乐乐的小兔已经走到门前，狐狸却迟迟没出来。彭泽宇听见老师叫名字才回过神，赶紧把纸偶伸到幕布前，台词又说错了顺序。老师没有批评他，让他坐下喝水，问昨晚休息得怎样。他承认睡得晚。林老师把这晚的任务减到收好纸偶和早点休息，并请安安再熟悉一遍狐狸的台词，作为备用。彭泽宇听见备用两个字，心里忽然有点紧。","image":"growth-consequences/empty-stage-place"},
    {"title":"越想演好，越舍不得停","content":"回家后，爸爸和他把纸偶装进盒子，提前准备衣服。到了睡前，彭泽宇却担心备用演员比自己演得好，又把台词拿出来默念。他想再确认一遍，每念完一遍又发现可以修改的地方。妈妈来时，发现他还在练，便陪他把担心说出来，再把台词放到门外的书包里。夜终于安静下来，他却懊恼自己又把收尾拖长了。明早的演出已经很近，今晚不能替前几个晚上多长出时间。","image":"growth-consequences/empty-stage-place"},
    {"title":"幕布后面开始转圈的台词","content":"演出前，礼堂里响起观众找座位的声音。彭泽宇明明知道第一句是什么，轮到试声时却把后面的句子混在一起。他握着纸偶，眼皮沉得厉害，听不清老师连续说的两个提示。爸爸和老师带他去安静的休息区，确认他没有其他不舒服，让他先坐稳休息。他急得快哭了：再给我一次，我能站上去。老师看着他，知道这时需要照顾的是孩子，而不是赶紧把一个角色塞回舞台。","image":"growth-consequences/empty-stage-place"},
    {"title":"纸狐狸交到了另一双手里","content":"林老师决定让准备过的安安代演狐狸，并把几段复杂走位简化。乐乐也要临时改成慢一点的接话，后台忙着重新确认顺序。彭泽宇亲手把纸狐狸递过去，手指在木柄上停了一下。他不是被罚下台，而是当时的状态已经不适合承担整场演出。可是知道原因，并没有让难过变小。他盼了许多天的角色，此刻真的从自己手里离开了。幕布后面，原本留给他的位置空了下来。","image":"growth-consequences/empty-stage-place"},
    {"title":"掌声从门缝里传来","content":"爸爸陪他留在安静的休息室。演出开始后，他断断续续听见音乐和掌声。到了狐狸欢迎朋友的那一幕，他抬起头，听见安安的声音说出了自己练过许多遍的台词。奶奶正在观众席上，她看到的是另一双手举起狐狸。彭泽宇把脸埋进爸爸的衣服，小声问能不能下午再演一次。爸爸抱着他，说今天剧场还有其他活动，不能把这一场倒回开头。他没有再说话，只握着空空的纸偶袋。","image":"growth-consequences/empty-stage-place"},
    {"title":"谢谢和难过可以一起说","content":"散场后，安安把狐狸送回来，说刚才自己也很紧张，有一段差点忘词。彭泽宇向她道谢，又向临时改台词的乐乐道歉。乐乐说今天真的忙乱，以后希望他提前告诉大家状态。彭泽宇承认自己早在彩排时就很困，却只想着多练几遍。他没有要求伙伴说没关系，也没有把代演当作谁抢走了角色。他还是难过，但知道那几位伙伴是在帮整场戏走到结尾。","image":"growth-consequences/empty-stage-place"},
    {"title":"把夜晚往前安排","content":"休息好以后，他和家人一起回看这几晚：动画没有及时停，手工收尾太晚，担心演不好又加练。他们决定晚饭后练一小段，睡前不再修改台词；未完成的想法画在明天再做的小卡片上。爸爸也把自己的手机收起来，陪他按顺序洗漱、选短故事、关灯。彭泽宇提出，如果躺下还在担心，就直接告诉大人，不再偷偷拿出纸偶。他们把办法试在普通日子里，而不是只等下一次演出。","image":"growth-consequences/empty-stage-place"},
    {"title":"不是每个晚上都一样顺利","content":"有一晚他又想把手工做完，手指捏着最后一条尾巴不放。妈妈提醒他看看明天再做的小卡片，他犹豫很久，还是把尾巴装进盒子。另一天关灯后，他担心伙伴以后都不选自己，便把爸爸叫回来聊了一会儿。睡前安排并没有让所有担心立刻消失，但他不用一个人靠熬夜对付它们了。慢慢地，早晨醒来不再总是那么费劲，排练时也能更清楚地接住下一句台词。","image":"growth-consequences/empty-stage-place"},
    {"title":"先从一棵树开始","content":"几周后，班级安排小型影子戏。彭泽宇想再次演狐狸，老师建议先承担一段较短的树木旁白，看看排练和休息能不能都安排好。他接受了，也和安安互相熟悉对方的台词，约好谁不舒服就及时告诉老师。正式表演那天，他清楚地念完旁白，稳稳举住纸树。掌声响起时，他笑了。这一次成功很小，却是他每天按时收尾、如实沟通之后，能够踏实接住的工作。","image":"growth-consequences/empty-stage-place"},
    {"title":"那张没用上的座位合影","content":"奶奶后来和他补拍了一张拿着纸狐狸的照片，两个人都笑得很开心。但原先那场演出的视频里，狐狸仍由安安操控，彭泽宇不会因为后来进步就出现在幕布后。他把纸偶收回盒子，没有剪掉视频中那一段。又到晚上，手工还剩一点没完成，他写下明天接着做，主动去洗漱。走过盒子时，他轻轻说：狐狸也下班了。房间的灯按约定暗下来，明天终于不必再向今晚讨时间。","image":"growth-consequences/empty-stage-place"}
  ]
}', 1, 3),
(624, 155, '舞台与休息问答', 'QUIZ', '{
  "type":"QUIZ",
  "items":[
    {"question":"彭泽宇演出前状态不好，故事交代了怎样的过程？","options":["连续几晚推迟休息，彩排已显疲惫，仍继续拖晚","只因为他不喜欢狐狸","只因为安安站在旁边"],"answer":0,"image":"growth-consequences/empty-stage-place"},
    {"question":"老师安排安安代演，主要是为什么？","options":["要让彭泽宇当众难堪","彭泽宇需要休息，同时让已准备的同伴接替演出","希望大家以后都不要睡觉"],"answer":1,"image":"growth-consequences/empty-stage-place"},
    {"question":"对临时接替的伙伴，哪种回应更合适？","options":["责怪她抢走角色","要求她也退出演出","感谢帮助，承认给伙伴增加的准备负担"],"answer":2,"image":"growth-consequences/empty-stage-place"},
    {"question":"彭泽宇因担心忘词，睡前总想继续练，怎样处理更好？","options":["向大人说出担心，把练习提前安排，按约定收尾","一直练到自己完全不担心","不告诉任何人，躲着练"],"answer":0,"image":"growth-consequences/empty-stage-place"},
    {"question":"后来的短旁白演好了，是否意味着原先的损失消失了？","options":["是，原视频会自动换成他","不是，他进步了，但原来那场演出已经错过","是，安安从未替他上过场"],"answer":1,"image":"growth-consequences/empty-stage-place"},
    {"question":"故事中的改进为什么需要家人一起参与？","options":["孩子从此不需要自己做任何事","大人要替孩子完成表演","家人能帮助安排收尾、处理担心，并持续支持休息习惯"],"answer":2,"image":"growth-consequences/empty-stage-place"}
  ]
}', 2, 3),

(625, 156, '被藏起来的裂缝', 'READING', '{
  "type":"READING",
  "items":[
    {"title":"小镇交给了保管员","content":"班级准备办黏土小镇展，安安做邮局，乐乐做面包店，彭泽宇负责给作品贴名牌。老师还请他当布展小助手，提醒大家拿放时扶住托盘，发现问题立即报告。最特别的是安安的邮局，门前有一只很小的鸟，是她和外公一起捏的。她把邮局放在展示架旁，说等老师检查后再摆上去。彭泽宇看着整整齐齐的小房子，很喜欢自己被大家信任的感觉。","image":"growth-consequences/hidden-crack"},
    {"title":"桌边那一下闷响","content":"整理名牌时，彭泽宇想从低矮展示架后面捡一支笔，没有先请旁边的同学让出通道。他一转身，手肘撞上了架子的侧边，木板发出闷闷的一声。侧面的连接处裂开一条细缝，上层板略微倾斜。他赶紧扶住，发现暂时还能立着。周老师正在教室另一边清点作品，只要叫一声就会过来。他张了张嘴，又想起自己胸前刚拿到的布展小助手名牌。","image":"growth-consequences/hidden-crack"},
    {"title":"看不见，就像没发生","content":"彭泽宇想，如果老师知道自己撞坏了架子，会不会马上换人？他拿一张装饰纸贴在侧边，把裂缝盖住，又把歪板轻轻推回去。纸只遮住了木头，并没有让连接处变牢。他却往后退了两步，觉得远看没什么不同。乐乐问刚才是什么声音，他说是笔掉了。那句话出口后，彭泽宇忽然不敢再看架子的侧面。教室里每个人还在忙，只有他知道纸后面多了什么。","image":"growth-consequences/hidden-crack"},
    {"title":"又一次可以说出来的时候","content":"布展前，老师按流程检查架子，发现上层板有点歪，就问有没有碰撞过，最近有没有异常。彭泽宇站在旁边，手心开始出汗。如果现在说明，老师就会拆开装饰纸检查连接处。他却摇头，说一直是这样的。老师检查可见位置后重新摆正，决定只放少量轻作品，随后去取防滑垫。安安把托盘推近，轻声提醒他扶一下。那条没说出口的裂缝，跟着他的沉默留在了架子里。","image":"growth-consequences/hidden-crack"},
    {"title":"邮局从高处落下来","content":"老师回来后，两人开始把轻巧的房子放到低架上。受损的连接处突然松开，上层板一斜，邮局和面包店一起滑落。老师马上让孩子退后，拦住伸手去接的彭泽宇，没有让任何人碰碎片。没有人受伤，桌上的邮局却裂成几块，那只小鸟也断了翅膀。教室安静下来。安安蹲下看了一眼，又站起来，双手抱着空托盘，问：刚才到底发生了什么？","image":"growth-consequences/hidden-crack"},
    {"title":"这回不能只说对不起","content":"彭泽宇的眼泪一下涌出来。他先说对不起，老师请他站到安全的地方，等能说话时讲清经过。他终于说出撞架子、遮裂缝、回答没有碰过的每一步。老师也承认自己的检查没有发现隐藏损坏，接下来要停用架子并重新检查布展设备。彭泽宇看着那张装饰纸，明白第一次碰撞本来可以及时处理，后来的隐瞒却让大家依据错误的信息，把珍贵的作品放了上去。","image":"growth-consequences/hidden-crack"},
    {"title":"空出来的邮局位置","content":"展览当天，安安没有带一座崭新的邮局来。她和外公原本只在那个周末一起有时间，来不及再做同样的作品。老师征得她同意，放了一张制作过程照片，原定摆邮局的位置空着。乐乐的面包店修好了墙，但屋顶留下接缝。彭泽宇想帮安安重新捏，她说今天不想一起做，需要缓一缓。他停下伸出的手，没有说自己已经道歉了，为什么她还不高兴。","image":"growth-consequences/hidden-crack"},
    {"title":"名牌暂时收进抽屉","content":"老师和彭泽宇商量，接下来他可以继续参加活动，但暂时不独自负责保管同伴的作品，先和大人一起做核对和记录。布展小助手的名牌收进抽屉，等大家看到稳定、诚实的行动，再讨论是否恢复职责。他难过地问是不是以后说什么都没人信了。老师说犯错不等于你永远是坏孩子，但别人需要证据知道东西能放心交给你。彭泽宇望向那只空托盘，第一次知道信任也会受损。","image":"growth-consequences/hidden-crack"},
    {"title":"补救先听主人的决定","content":"在老师陪同下，他分别问两位伙伴希望怎样补救。乐乐同意他帮忙补充材料并整理制作照片，安安只希望先把残片安全收好，不要擅自粘接。他答应按他们的决定来。家长负责处理需要购买的材料，老师负责损坏的架子，彭泽宇做自己能完成的记录、整理和协助。他把经过完整告诉爸爸，没有删去那次摇头。讲到一半他又哭了，但这回没有让难堪变成下一句假话。","image":"growth-consequences/hidden-crack"},
    {"title":"第二条裂缝出现的时候","content":"两周后整理画具，彭泽宇发现一个托盘边缘裂了。他的第一反应仍是把它放回去，免得大家以为又是自己弄坏的。手伸到一半，他停下来，把托盘单独放好，立即告诉老师：我发现这里裂了，不知道什么时候裂的，请先别用。他没有猜一个人来负责，也没有保证绝对安全。老师记录问题并换了托盘。当天没有掌声，没有新名牌，也没有作品掉下来。事情就在被发现的地方停住了。","image":"growth-consequences/hidden-crack"},
    {"title":"有人开始把托盘递给他","content":"之后几次活动，他都和老师一起检查物品，发现少了什么、松了什么就如实记录。有一天安安要搬一幅已经装盒的纸画，问他能不能扶住另一边。他先确认怎么拿，两个人慢慢把盒子放稳。安安说谢谢，但仍没有让他独自拿黏土作品。彭泽宇接受了这个界限。比起催大家相信自己，他更想让下一次交接也平稳结束。那句谢谢很短，他却记了很久。","image":"growth-consequences/hidden-crack"},
    {"title":"裂缝没有被画成花纹","content":"学期结束，乐乐的面包店放在展示柜里，屋顶的接缝还在；安安和外公后来做了一座新的邮局，把旧小鸟单独留在盒子里。彭泽宇恢复了部分布展工作，搬易碎作品仍要和大人配合。他没有把这些讲成一次漂亮的冒险。翻到记录本最后一页，他写下发现问题就停下，说清知道的，不知道也如实说。合上本子时，他看见新的展台侧面干干净净，再没有一张用来遮住问题的装饰纸。","image":"growth-consequences/hidden-crack"}
  ]
}', 1, 3),
(626, 156, '裂缝与信任问答', 'QUIZ', '{
  "type":"QUIZ",
  "items":[
    {"question":"哪一步让原本可以及时处理的损坏继续影响了同伴？","options":["发现裂缝后马上停用","把裂缝遮住，并在老师询问时否认碰撞","如实报告自己知道的情况"],"answer":1,"image":"growth-consequences/hidden-crack"},
    {"question":"作品滑落时，为什么老师让大家退后？","options":["避免孩子接落物或碰碎片受伤","不让任何人知道作品坏了","要让裂缝变得更大"],"answer":0,"image":"growth-consequences/hidden-crack"},
    {"question":"安安暂时不想一起重做，彭泽宇应该怎样回应？","options":["要求她立刻接受道歉","趁她不在，擅自粘好碎片","尊重她的感受与决定，再询问她需要什么帮助"],"answer":2,"image":"growth-consequences/hidden-crack"},
    {"question":"老师也检查漏了，是否意味着彭泽宇不用为隐瞒负责？","options":["是，只要大人有疏漏就可以说假话","不是，大人要改进检查，他也要承担隐瞒造成的影响","是，因为装饰纸能修好木架"],"answer":1,"image":"growth-consequences/hidden-crack"},
    {"question":"后来发现托盘裂了，但不知道是谁弄的，应该怎么说？","options":["说明发现的位置和问题，如实说不知道原因，先请大人检查","随便指认一个人，避免自己被怀疑","说托盘没有问题，继续交给别人"],"answer":0,"image":"growth-consequences/hidden-crack"},
    {"question":"故事怎样表现信任正在慢慢恢复？","options":["一句道歉后，所有职责立刻恢复","旧作品恢复如新，大家不再记得事故","持续如实记录和可靠交接，伙伴逐步愿意再次合作"],"answer":2,"image":"growth-consequences/hidden-crack"}
  ]
}', 2, 3);
